# ===========================================================================
# MODELS: 1-D Mars models for the env slice, (dtop_km, dbot_km, vp_m_s,
# vs_m_s, rho_kg_m3), layer boundaries 200 m quantised.
#
#   TAYAK  — Khan et al. 2016 full-planet reference (TAYAK.mod), crust
#            0-1 / 1-10 / 10-77.4 km, Moho on-grid at 77.4 km.
#   invA_r1..r8, invB_r1..r8 — generated by tools/ensemble_pick.jl from
#            the InSight joint-Ps-RF crust ensembles (Knapmeyer-Endrun
#            et al. 2021, Science 373, doi:10.18715/IPGP.2021.kqwc4yaf),
#            8 members per ensemble, evenly spaced in Moho-depth rank
#            across the full 5000-member posterior.
# config/models_gen.jl is GENERATED (do not hand-edit); regenerate with
#   julia tools/ensemble_pick.jl
# ===========================================================================

const TAYAK_LAYERS = [
    (0.0,   1.0,   3677.71, 1739.80, 1865.33),
    (1.0,   10.0,  4952.25, 2780.97, 2271.82),
    (10.0,  77.4,  5846.66, 3281.16, 2681.72),
    (77.4,  80.0,  7400.90, 4246.33, 3388.58),
    (80.0,  100.0, 7413.64, 4247.35, 3393.07),
    (100.0, 110.0, 7436.12, 4180.19, 3399.95),
    (110.0, 120.0, 7446.65, 4181.17, 3403.31),
]

const MARS_MODELS = Dict{String,Vector{NTuple{5,Float64}}}(
    "TAYAK" => TAYAK_LAYERS)
const MARS_MOHO = Dict{String,Float64}("TAYAK" => 77.4)
const MARS_BOUNDS = Dict{String,Vector{Float64}}("TAYAK" => [1.0, 10.0])

# merge the generated ensemble members (models_gen.jl writes
# ENSEMBLE_MODELS / ENSEMBLE_MOHO / ENSEMBLE_BOUNDS)
_genfile = joinpath(@__DIR__, "models_gen.jl")
if isfile(_genfile)
    include(_genfile)
    merge!(MARS_MODELS, ENSEMBLE_MODELS)
    merge!(MARS_MOHO, ENSEMBLE_MOHO)
    merge!(MARS_BOUNDS, ENSEMBLE_BOUNDS)
end

"crustal interface depths (km) ABOVE the Moho for a model"
function mars_boundaries(model::String)
    get(MARS_BOUNDS, model, Float64[])
end
